def _ensure_package(name: str) -> _bundle_types.ModuleType:
    existing = _bundle_sys.modules.get(name)
    if existing is not None:
        return existing
    module = _bundle_types.ModuleType(name)
    module.__file__ = _BUNDLE_FILE
    module.__package__ = name.rpartition(".")[0]
    # Direct spec loading is used by contract tests and by portable launchers.
    # Keep the public tools package importable afterwards instead of leaving a
    # synthetic package with an empty search path in sys.modules.
    module.__path__ = (  # type: ignore[attr-defined]
        [str(_BundlePath(_BUNDLE_FILE).resolve().parent)]
        if name == "tools"
        else []
    )
    _bundle_sys.modules[name] = module
    if "." in name:
        parent_name, child = name.rsplit(".", 1)
        parent = _ensure_package(parent_name)
        setattr(parent, child, module)
    return module


def _load_bundled_module(name: str, *, package: bool = False) -> _bundle_types.ModuleType:
    raw = _BUNDLED_MODULES[name]
    source = _bundle_zlib.decompress(_bundle_base64.b85decode(raw.encode("ascii"))).decode("utf-8")
    if package:
        module = _ensure_package(name)
    else:
        if "." in name:
            parent_name, child = name.rsplit(".", 1)
            parent = _ensure_package(parent_name)
        else:
            parent = None
            child = name
        module = _bundle_types.ModuleType(name)
        module.__file__ = _BUNDLE_FILE
        module.__package__ = name.rpartition(".")[0]
        _bundle_sys.modules[name] = module
        if parent is not None:
            setattr(parent, child, module)
    exec(compile(source, f"{_BUNDLE_FILE}::{name}", "exec"), module.__dict__)
    return module


